const TEXTURE_SIZE = 1024;
const PARTICLE_COUNT = TEXTURE_SIZE * TEXTURE_SIZE;
const PARTICLE_SIZE = 20;
const STEP_PER_FRAME = 1;
const FRAME_RATE = 30;
const DELTA_TIME = 0.00125;

let fontLoaded = false;

let simulationShader;
let renderShader;

let particleVBO;

let next;
let prev;

let sizeX;
let sizeY;
let sizeDot;

let up;
let down;
let left;
let right;

let i = 0;
let j = 0;
let cycleTime = 10;
let cycleRotation = 0.6;

const defaultVert = `
precision highp float;

attribute vec3 aPosition;
attribute vec2 aTexCoord;
attribute vec4 aVertexColor;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
varying vec2 vTexCoord;


void main() {
  vec4 viewModelPosition = uModelViewMatrix * vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * viewModelPosition;

  vTexCoord = aTexCoord.xy  ;
}`;

const initializationFrag = `
precision highp float;

uniform float u_texture_size;
uniform float u_seed;
uniform float u_rotation;
uniform float u_time;

varying vec2 vTexCoord;


vec3 mod289(vec3 x) {
  return x - floor(x * (1.0 / 289.0)) * 289.0;
}

vec2 mod289(vec2 x) {
  return x - floor(x * (1.0 / 289.0)) * 289.0;
}

vec3 permute(vec3 x) {
  return mod289(((x*34.0)+10.0)*x);
}

float snoise(vec2 v)
  {
  const vec4 C = vec4(0.211324865405187,  // (3.0-sqrt(3.0))/6.0
                      0.366025403784439,  // 0.5*(sqrt(3.0)-1.0)
                     -0.577350269189626,  // -1.0 + 2.0 * C.x
                      0.024390243902439); // 1.0 / 41.0
// First corner
  vec2 i  = floor(v + dot(v, C.yy) );
  vec2 x0 = v -   i + dot(i, C.xx);

// Other corners
  vec2 i1;
  //i1.x = step( x0.y, x0.x ); // x0.x > x0.y ? 1.0 : 0.0
  //i1.y = 1.0 - i1.x;
  i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
  // x0 = x0 - 0.0 + 0.0 * C.xx ;
  // x1 = x0 - i1 + 1.0 * C.xx ;
  // x2 = x0 - 1.0 + 2.0 * C.xx ;
  vec4 x12 = x0.xyxy + C.xxzz;
  x12.xy -= i1;

// Permutations
  i = mod289(i); // Avoid truncation effects in permutation
  vec3 p = permute( permute( i.y + vec3(0.0, i1.y, 1.0 ))
		+ i.x + vec3(0.0, i1.x, 1.0 ));

  vec3 m = max(0.5 - vec3(dot(x0,x0), dot(x12.xy,x12.xy), dot(x12.zw,x12.zw)), 0.0);
  m = m*m ;
  m = m*m ;

// Gradients: 41 points uniformly over a line, mapped onto a diamond.
// The ring size 17*17 = 289 is close to a multiple of 41 (41*7 = 287)

  vec3 x = 2.0 * fract(p * C.www) - 1.0;
  vec3 h = abs(x) - 0.5;
  vec3 ox = floor(x + 0.5);
  vec3 a0 = x - ox;

// Normalise gradients implicitly by scaling m
// Approximation of: m *= inversesqrt( a0*a0 + h*h );
  m *= 1.79284291400159 - 0.85373472095314 * ( a0*a0 + h*h );

// Compute final noise value at P
  vec3 g;
  g.x  = a0.x  * x0.x  + h.x  * x0.y;
  g.yz = a0.yz * x12.xz + h.yz * x12.yw;
  return 130.0 * dot(m, g);
}

float random (vec2 st) {
    st += vec2(u_seed,u_seed);
    return fract(sin(dot(st, vec2(12.9898,78.233))) * 43758.5453);
}

vec2 rotate(vec2 uv, float angle) {
    float c = cos(angle);
    float s = sin(angle);
    mat2 rot = mat2(c, -s,
                    s,  c);
    uv -= 0.5;
    uv = rot * uv;
    uv += 0.5;
    return uv;
}

void main() {
  vec2 uv = gl_FragCoord.xy / u_texture_size *5.0;
  uv.x += u_time * 0.02;
  uv.x = snoise(uv) * 0.9 + 0.1;
  uv.y -= u_time * 0.02;
  uv.y = snoise(uv + vec2(234556)) * 0.9 + 0.1;  
  uv = rotate(uv, u_rotation);

  float z = snoise(uv * u_time * 0.001 + vec2(256)) *0.1 + 0.85 ;
  gl_FragColor = vec4(uv, z,1.0);
}`;

const blendFrag = `
precision highp float;

uniform sampler2D u_prev;
uniform sampler2D u_next;
uniform float u_mix;

varying vec2 vTexCoord;

void main() {
  vec4 a = texture2D(u_prev, vTexCoord);
  vec4 b = texture2D(u_next, vTexCoord);
  gl_FragColor = mix(a, b, u_mix);
}`;


// Adapted p5.FIP (Fast Image Processing) by prontopablo 
// Original code licenced as MIT
// https://github.com/prontopablo/p5.FIP
const blurFragShader = `
        precision highp float;
        varying vec2 vTexCoord;
        uniform sampler2D tex0;
        uniform vec2 canvasSize;
        uniform float blurRadius;  // New parameter to control blur size

        void main(void) {
            // Calculate the dynamic texOffset based on the texture size and blurRadius
            vec2 texOffset = blurRadius / canvasSize;

            // Sample points based on the blur radius
            vec2 tc0 = vTexCoord.st + vec2(-texOffset.s, -texOffset.t);
            vec2 tc1 = vTexCoord.st + vec2(0.0, -texOffset.t);
            vec2 tc2 = vTexCoord.st + vec2(texOffset.s, -texOffset.t);
            vec2 tc3 = vTexCoord.st + vec2(-texOffset.s, 0.0);
            vec2 tc4 = vTexCoord.st + vec2(0.0, 0.0);
            vec2 tc5 = vTexCoord.st + vec2(texOffset.s, 0.0);
            vec2 tc6 = vTexCoord.st + vec2(-texOffset.s, texOffset.t);
            vec2 tc7 = vTexCoord.st + vec2(0.0, texOffset.t);
            vec2 tc8 = vTexCoord.st + vec2(texOffset.s, texOffset.t);

            // Sample the colors at the given offsets
            vec4 col0 = texture2D(tex0, tc0);
            vec4 col1 = texture2D(tex0, tc1);
            vec4 col2 = texture2D(tex0, tc2);
            vec4 col3 = texture2D(tex0, tc3);
            vec4 col4 = texture2D(tex0, tc4);
            vec4 col5 = texture2D(tex0, tc5);
            vec4 col6 = texture2D(tex0, tc6);
            vec4 col7 = texture2D(tex0, tc7);
            vec4 col8 = texture2D(tex0, tc8);

            // Weighted sum of all the neighboring pixels for blur
            vec4 sum = (1.0 * col0 + 2.0 * col1 + 1.0 * col2 +  
                        2.0 * col3 + 4.0 * col4 + 2.0 * col5 +
                        1.0 * col6 + 2.0 * col7 + 1.0 * col8) / 16.0;

            // Output the blurred color
            gl_FragColor = vec4(sum.rgb, 1.0);
        }
`;

function setup() {

	if (windowWidth > windowHeight){
		sizeX = windowHeight / 0.7;
		sizeY = windowHeight / 0.9;
	}else{
		sizeX = windowWidth 
		sizeY = windowWidth
	}
	// const base = max(windowWidth, windowHeight)
	// sizeX = base/3
	// sizeY = base
	// sizeDot = (base/TEXTURE_SIZE) / base 

	createCanvas(windowWidth, windowHeight, WEBGL);
	frameRate(30)

	// Compile shaders
	initializationShader = createShader(defaultVert, initializationFrag);
	blendShader = createShader(defaultVert, blendFrag);
	blurShader = createFilterShader(blurFragShader)
	blurShader.setUniform('blurRadius', 2); 
	blurShader.setUniform('u_aspect', windowWidth / windowHeight);

	// Init coordinat
	up = -windowHeight / 2;
	down = windowHeight / 2;
	left = -windowWidth / 2;
	right = windowWidth / 2;

	// Init Simulation buffers
	prev = createFramebuffer({
		width: TEXTURE_SIZE,
		height: TEXTURE_SIZE,
		format: FLOAT,
		textureFiltering: NEAREST,
	});

	current = createFramebuffer({
		width: TEXTURE_SIZE,
		height: TEXTURE_SIZE,
		format: FLOAT,
		textureFiltering: NEAREST,
	});

	next = createFramebuffer({
		width: TEXTURE_SIZE,
		height: TEXTURE_SIZE,
		format: FLOAT,
		textureFiltering: NEAREST,
	});

	next.begin();
	shader(initializationShader);
	initializationShader.setUniform("u_texture_size", TEXTURE_SIZE);
	initializationShader.setUniform("u_rotation", j);
	initializationShader.setUniform("u_seed", random());
	noStroke();
	rect(-TEXTURE_SIZE / 2, -TEXTURE_SIZE / 2, TEXTURE_SIZE, TEXTURE_SIZE);
	resetShader();
	next.end();

}

function draw() {
	// if (i >= cycleTime ){
	// 	return
	// }
	background(22)

	i += 1;
	if (i % cycleTime == 0) {
		j += cycleRotation; 

		// Swap prev and next
		[prev, next] = [next, prev];

		// Compute a new step
		next.begin();
		clear();
		shader(initializationShader);
		initializationShader.setUniform("u_texture_size", TEXTURE_SIZE);
		initializationShader.setUniform("u_seed", random());
		initializationShader.setUniform("u_rotation", j);
		initializationShader.setUniform("u_time", i);
		noStroke();
		rect(-TEXTURE_SIZE / 2, -TEXTURE_SIZE / 2, TEXTURE_SIZE, TEXTURE_SIZE);
		resetShader();
		next.end();

	}

	current.begin();
	shader(blendShader);
	blendShader.setUniform("u_prev", prev);
	blendShader.setUniform("u_next", next);
	blendShader.setUniform("u_mix", (i % cycleTime) / cycleTime);
	noStroke();
	rect(-TEXTURE_SIZE / 2, -TEXTURE_SIZE / 2, TEXTURE_SIZE, TEXTURE_SIZE);
	resetShader();
	current.end();

	push();
translate(0, 0, 0);   // center of WEBGL canvas
rotate(i / 1000);

	// Render the simulation data
	const cols = Math.ceil(max(windowWidth,windowHeight) / sizeX);
	const rows = Math.ceil(max(windowWidth,windowHeight)/ sizeY);
	const zoomX = sizeX / TEXTURE_SIZE
	const zoomY = sizeY / TEXTURE_SIZE


	for (let row = -rows; row < rows; row++) {
		for (let col = -cols; col < cols; col++) {
			const x = left + col * sizeX - col * zoomX;
			const y = up + row * sizeY - row * zoomY;

			// Determine flip factors
			let scaleX = (col % 2 !== 0) ? -1 : 1;
			let scaleY = (row % 2 !== 0) ? -1 : 1;

			push();
			// 1. Move to the center of the current tile
			translate(x + sizeX / 2, y + sizeY / 2);

			// 2. Apply both horizontal and vertical scaling
			scale(scaleX, scaleY);

			// 3. Draw image centered on the translation point
			image(current, -sizeX / 2, -sizeY / 2, sizeX, sizeY);
			pop();
		}
	}
	filter(blurShader)
	pop()	
}

